      "reason": "Repair and replace both survive."
    },
    {
      "candidate_id": "NI-006",
      "ruling": "keep",
      "basis": "degraded",
      "reason": "Repair survives, while diagnosis 2nd and return were removed by earlier candidates, so the candidate remains partially actionable."
    }
  ],
  "reorder_suggestion": [
    "CT-001",
    "EXC-001",
    "AE-001",
    "CA-001",
    "CBW-001",
    "EXC-002",
